Tabel Deskripsi

# Fungsi untuk membuat tabel distribusi 
buat_tabel &lt;- function(var, nama_var){
  tab &lt;- table(var)
  df &lt;- data.frame(
    Variabel = nama_var,
    Kategori = names(tab),
    Jumlah = as.vector(tab),
    Persen = round(prop.table(tab) * 100, 1)
  )
  return(df)
}

# Buat tabel untuk setiap variabel 
tabel_kelamin   &lt;- buat_tabel(wvs4idn$jenis_kelamin, "Jenis Kelamin")
tabel_usia      &lt;- buat_tabel(wvs4idn$usia, "Kelompok Usia")
tabel_pendidikan&lt;- buat_tabel(wvs4idn$Pend_done, "Jenjang Pendidikan")
tabel_agama     &lt;- buat_tabel(wvs4idn$Kepercayaan, "Agama")

# Gabungkan semua tabel jadi satu 
tabel_final &lt;- rbind(tabel_kelamin, tabel_usia, tabel_pendidikan, tabel_agama)

# Membuat tabel data responden
ft &lt;- flextable(tabel_final) |&gt;
  set_header_labels(
    Variabel = "Variabel", 
    kategori_summary = "Kategori", 
    Jumlah = "Jumlah", 
    Persen = "Persen (%)"
  ) |&gt;
  add_header_lines("Tabel 2. Statistik Deskriptif Data Responden WVS 4") |&gt;
  merge_v(j = "Variabel") |&gt;
  align(align = "center", part = "all") |&gt;

  # FONT Times New Roman
  font(fontname = "Times New Roman", part = "all") |&gt;
  fontsize(size = 12, part = "all") |&gt;

  # Header lebih tebal
  bold(part = "header") |&gt;
  bold(i = 1, part = "header") |&gt;

  autofit()

