## Analisis Regresi WVS Indonesia 4
uji_regresi_4 &lt;- lm(Religiositas ~ Pend_done, data = WVS4IDN)

# untuk hasil R2
r2 &lt;- summary(uji_regresi_4)$r.squared
adj_r2 &lt;- summary(uji_regresi_4)$adj.r.squared

# ambil hasil regresi
hasil_reg &lt;- tidy(uji_regresi_4, conf.int = TRUE) |&gt;
  mutate(
    Variabel = dplyr::recode(term,
      "(Intercept)" = "(Intercept)",
      "Pend_doneSMP" = "SMP",
      "Pend_doneSMA" = "SMA",
      "Pend_doneSarjana" = "Sarjana"
    ),
    estimate = round(estimate, 3),
    std.error = round(std.error, 3),
    CI = paste0(
      round(conf.low, 3),
      " – ",
      round(conf.high, 3)
    ), 
    p.value = ifelse(p.value &lt; 0.001, "&lt;0.001", round(p.value, 3)),
    Signif = case_when(
      p.value == "&lt;0.001" ~ "***",
      as.numeric(p.value) &lt; 0.01 ~ "**",
      as.numeric(p.value) &lt; 0.05 ~ "*",
      TRUE ~ ""
    )
  ) |&gt;
  select(Variabel, estimate, std.error, CI, p.value, Signif) |&gt;
  rename(
    Koefisien = estimate,
    `Std. Error` = std.error,
    `CI (95%)` = CI,
    `p-value` = p.value
  )

