# buat tabel
ft &lt;- flextable(hasil_reg) |&gt;
  set_caption("Tabel 8. Analisis Regresi Pengaruh Pendidikan terhadap Religiositas WVS 4") |&gt;
  align(align = "center", part = "all") |&gt;
  colformat_num(
    j = c("Koefisien", "Std. Error", "p-value"),
    digits = 3
  ) |&gt;
  bold(part = "header") |&gt;
  font(fontname = "Times New Roman", part = "all") |&gt;
  fontsize(size = 12, part = "all") |&gt;
  autofit() |&gt;
  add_footer_lines(
    values = paste0(
      "R² = ", round(r2, 3),
      "; Adjusted R² = ", round(adj_r2, 3)
    )
  ) |&gt; font(fontname = "Times New Roman", part = "footer")

